window.addEventListener("ineo-auth-ready",async e=>{
  const user=e.detail?.user;if(!user)return;
  currentUser=user;
  try{await loadBusinesses()}catch(err){console.error("iNeo negocios:",err)}
  try{renderBusinessSwitcher()}catch(err){console.error("iNeo selector:",err)}
  try{bindRealtime()}catch(err){console.error("iNeo datos:",err)}
  try{await loadSettings()}catch(err){console.error("iNeo configuración:",err)}
  try{showView("dashboard")}catch(err){console.error("iNeo dashboard:",err)}
});

const $=s=>document.querySelector(s), $$=s=>document.querySelectorAll(s);
const loginScreen=$("#loginScreen"),appShell=$("#appShell"),content=$("#content"),pageTitle=$("#pageTitle"),modal=$("#modal"),modalBody=$("#modalBody"),toast=$("#toast");
let currentUser=null,currentBusinessId=null,currentBusinessName="Mi negocio",products=[],customers=[],debts=[],sales=[],movements=[],suppliers=[],purchases=[],stockMoves=[];
let unsubs=[];let cart=[];let businesses=[];let appSettings={businessName:"Mi negocio",lowStockDefault:0,notifications:true};

const money=n=>new Intl.NumberFormat("es-AR",{style:"currency",currency:"ARS",maximumFractionDigits:0}).format(Number(n)||0);
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[c]));
const use=id=>`<svg><use href="#${id}"/></svg>`;
const uid=()=>Math.random().toString(36).slice(2,9);
const todayKey=d=>{if(!d)return ""; if(d.toDate)d=d.toDate(); if(typeof d?.seconds==="number")d=new Date(d.seconds*1000); if(typeof d==="string")d=new Date(d); return new Intl.DateTimeFormat("en-CA",{timeZone:"America/Argentina/Buenos_Aires"}).format(d)};
const dateLabel=d=>{if(!d)return "-";if(d.toDate)d=d.toDate();if(typeof d?.seconds==="number")d=new Date(d.seconds*1000);return new Intl.DateTimeFormat("es-AR",{day:"2-digit",month:"short",hour:"2-digit",minute:"2-digit"}).format(new Date(d)).replace(".","")};
function showLoginScreen(){
  const login=$("#loginScreen"),register=$("#registerScreen");
  if(register){register.classList.add("hidden");register.setAttribute("aria-hidden","true");register.style.display="none";}
  if(login){login.classList.remove("hidden");login.setAttribute("aria-hidden","false");login.style.display="grid";}
}
function showRegisterScreen(){
  const login=$("#loginScreen"),register=$("#registerScreen");
  if(login){login.classList.add("hidden");login.setAttribute("aria-hidden","true");login.style.display="none";}
  if(register){register.classList.remove("hidden");register.setAttribute("aria-hidden","false");register.style.display="grid";}
}

function notify(msg){toast.textContent=msg;toast.classList.add("show");setTimeout(()=>toast.classList.remove("show"),2600)}
function openModal(title,body){$("#modalTitle").textContent=title;modalBody.innerHTML=body;modal.classList.remove("hidden")}
function closeModal(){modal.classList.add("hidden")}
$("#closeModal").onclick=closeModal;$(".modal-backdrop").onclick=closeModal;


function businessRoot(){return `usuarios/${currentUser.uid}/negocios/${currentBusinessId}`}
function businessCollection(name){return collection(db,`${businessRoot()}/${name}`)}
function businessDoc(name,id){return doc(db,`${businessRoot()}/${name}/${id}`)}
function userBusinessesRef(){return collection(db,`usuarios/${currentUser.uid}/negocios`)}
function slugId(name){return `${Date.now()}-${String(name||"negocio").toLowerCase().replace(/[^a-z0-9áéíóúñ]+/gi,"-").slice(0,28)}`}
async function legacyDataExists(){
  const names=["productos","clientes","deudas","ventas","movimientosCaja","proveedores","compras","movimientosStock"];
  const result={}; let total=0;
  for(const name of names){
    const snap=await getDocs(collection(db,`usuarios/${currentUser.uid}/${name}`));
    result[name]=snap.docs;
    total+=snap.size;
  }
  return {docs:result,total};
}
async function migrateLegacyBusiness(businessId){
  const legacy=await legacyDataExists();
  if(!legacy.total)return 0;
  const names=Object.keys(legacy.docs);
  let ops=[];
  let moved=0;
  for(const name of names){
    for(const d of legacy.docs[name]){
      ops.push({name,doc:d});
      if(ops.length===450){
        const batch=writeBatch(db);
        for(const op of ops)batch.set(doc(db,`usuarios/${currentUser.uid}/negocios/${businessId}/${op.name}/${op.doc.id}`),op.doc.data(),{merge:true});
        await batch.commit();
        moved+=ops.length; ops=[];
      }
    }
  }
  if(ops.length){
    const batch=writeBatch(db);
    for(const op of ops)batch.set(doc(db,`usuarios/${currentUser.uid}/negocios/${businessId}/${op.name}/${op.doc.id}`),op.doc.data(),{merge:true});
    await batch.commit();
    moved+=ops.length;
  }
  return moved;
}
async function loadBusinesses(){
  if(!currentUser)return;
  const legacyConfig=await getDoc(doc(db,`usuarios/${currentUser.uid}/config/general`));
  const legacyBusinessName=legacyConfig.exists()?String(legacyConfig.data().businessName||"Mi negocio"):"Mi negocio";
  const snap=await getDocs(userBusinessesRef());
  businesses=snap.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>String(a.nombre||"").localeCompare(String(b.nombre||"")));
  if(!businesses.length){
    const id=slugId(legacyBusinessName);
    await setDoc(doc(db,`usuarios/${currentUser.uid}/negocios/${id}`),{nombre:legacyBusinessName,creadoEn:serverTimestamp(),legacyImported:false},{merge:true});
    businesses=[{id,nombre:legacyBusinessName,legacyImported:false}];
  }
  currentBusinessId=localStorage.getItem(`ineo-current-business-${currentUser.uid}`)||businesses[0].id;
  if(!businesses.find(b=>b.id===currentBusinessId))currentBusinessId=businesses[0].id;
  const active=businesses.find(b=>b.id===currentBusinessId)||businesses[0];
  currentBusinessName=active.nombre||legacyBusinessName;
  appSettings.businessName=currentBusinessName;

  // Recovery/migration: preserve old data and copy it into the active business when needed.
  try{
    const legacy=await legacyDataExists();
    const productSnap=await getDocs(businessCollection("productos"));
    const needsMigration=legacy.total>0 && productSnap.size===0;
    if(needsMigration){
      const moved=await migrateLegacyBusiness(active.id);
      await setDoc(doc(db,`usuarios/${currentUser.uid}/negocios/${active.id}`),{legacyImported:true,legacyImportedCount:moved,legacyImportedAt:serverTimestamp()},{merge:true});
      active.legacyImported=true;
    }else if(!active.legacyImported){
      await setDoc(doc(db,`usuarios/${currentUser.uid}/negocios/${active.id}`),{legacyImported:true},{merge:true});
      active.legacyImported=true;
    }
  }catch(err){console.error("Migración de datos:",err);}
}
function renderBusinessSwitcher(){
  const host=$("#businessSwitcher");if(!host)return;
  host.innerHTML=`<button type="button" class="workspace business-switcher-btn" id="businessSwitcherBtn"><div class="workspace-avatar">${esc((currentBusinessName||"M").charAt(0).toUpperCase())}</div><div><small>NEGOCIO</small><strong>${esc(currentBusinessName||"Mi negocio")}</strong></div>${use("i-chevron")}</button>`;
  const btn=$("#businessSwitcherBtn");
  if(btn)btn.onclick=e=>{e.preventDefault();e.stopPropagation();openBusinessMenu()};
}
function openBusinessMenu(){
  const list=businesses.length?businesses:[{id:currentBusinessId,nombre:currentBusinessName||"Mi negocio"}];
  openModal("Mis negocios",`<div class="business-menu"><div class="business-list">${list.map(b=>`<button type="button" class="business-choice ${b.id===currentBusinessId?"active":""}" data-business-id="${esc(b.id)}"><div class="business-choice-icon">${esc((b.nombre||"M").charAt(0).toUpperCase())}</div><div><strong>${esc(b.nombre)}</strong><small>${b.id===currentBusinessId?"Negocio activo":"Cambiar a este negocio"}</small></div>${b.id===currentBusinessId?use("i-check"):""}</button>`).join("")}</div><div class="business-menu-note">${use("i-info")} Cada negocio mantiene su inventario, ventas, caja y clientes.</div><button type="button" class="btn primary full-btn" id="newBusinessBtn">${use("i-plus")} Crear otro negocio</button></div>`);
  document.querySelectorAll("[data-business-id]").forEach(b=>b.onclick=()=>switchBusiness(b.dataset.businessId));
  const nb=$("#newBusinessBtn");if(nb)nb.onclick=()=>businessModal();
}
function businessModal(){
  openModal("Crear nuevo negocio",`<form id="businessForm">
    <div class="field"><label>NOMBRE DEL NEGOCIO</label><input name="nombre" placeholder="Ej.: Tienda Centro" required autofocus></div>
    <div class="form-actions"><button type="button" class="btn" id="cancelBusiness">Cancelar</button><button class="btn save">Crear negocio</button></div>
  </form>`);
  $("#cancelBusiness").onclick=closeModal;
  $("#businessForm").onsubmit=async e=>{
    e.preventDefault(); const nombre=new FormData(e.target).get("nombre").trim(); if(!nombre)return;
    try{
      const id=slugId(nombre);
      await setDoc(doc(db,`usuarios/${currentUser.uid}/negocios/${id}`),{nombre,creadoEn:serverTimestamp(),legacyImported:true,legacyImportedCount:0},{merge:true});
      await loadBusinesses(); await switchBusiness(id);
    }catch(err){notify("No se pudo crear el negocio")}
  };
}
async function switchBusiness(id){
  const b=businesses.find(x=>x.id===id); if(!b||id===currentBusinessId&&document.body.classList.contains("modal-open")){ if(id===currentBusinessId)closeModal(); return; }
  currentBusinessId=id;
  currentBusinessName=b.nombre||"Mi negocio";
  localStorage.setItem(`ineo-current-business-${currentUser.uid}`,id);
  unsubs.forEach(fn=>fn?.());unsubs=[];
  products=[];customers=[];debts=[];sales=[];movements=[];suppliers=[];purchases=[];stockMoves=[];
  closeModal(); renderBusinessSwitcher(); bindRealtime(); showView("dashboard");
  notify(`Negocio activo: ${currentBusinessName}`);
}
function bindRealtime(){
  unsubs.forEach(fn=>fn?.());unsubs=[];if(!currentUser||!currentBusinessId)return;
  const sub=(ref,cb)=>{const off=onSnapshot(ref,cb);unsubs.push(off)};
  sub(businessCollection("productos"),snap=>{products=snap.docs.map(d=>({id:d.id,...d.data()}));refreshView()});
  sub(businessCollection("clientes"),snap=>{customers=snap.docs.map(d=>({id:d.id,...d.data()}));updateDebtBadge();refreshView()});
  sub(businessCollection("deudas"),snap=>{debts=snap.docs.map(d=>({id:d.id,...d.data()}));updateDebtBadge();refreshView()});
  sub(businessCollection("ventas"),snap=>{sales=snap.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>stamp(b.fecha)-stamp(a.fecha));refreshView()});
  sub(businessCollection("movimientosCaja"),snap=>{movements=snap.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>stamp(b.fecha)-stamp(a.fecha));if($("#pageTitle")?.textContent==="Caja")renderCash()});
  sub(businessCollection("proveedores"),snap=>{suppliers=snap.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>String(a.nombre||"").localeCompare(String(b.nombre||"")));if($("#pageTitle")?.textContent==="Proveedores")renderSuppliers()});
  sub(businessCollection("compras"),snap=>{purchases=snap.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>stamp(b.fecha)-stamp(a.fecha));if($("#pageTitle")?.textContent==="Compras")renderPurchases()});
  sub(businessCollection("movimientosStock"),snap=>{stockMoves=snap.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>stamp(b.fecha)-stamp(a.fecha));if($("#pageTitle")?.textContent==="Historial de stock")renderStockHistory()});
}

function stamp(v){if(!v)return 0;if(v.toDate)return v.toDate().getTime();if(typeof v.seconds==="number")return v.seconds*1000;return new Date(v).getTime()||0}
function refreshView(){const t=$("#pageTitle")?.textContent;if(t==="Inventario")renderInventory();else if(t==="Clientes")renderCustomers();else if(t==="Fiados / Deudas")renderDebts();else if(t==="Resumen")renderDashboard();else if(t==="Ventas")renderSales(true);else if(t==="Historial de ventas")renderSalesHistory();else if(t==="Reportes")renderReports();else if(t==="Proveedores")renderSuppliers();else if(t==="Compras")renderPurchases();else if(t==="Historial de stock")renderStockHistory()}
function updateDebtBadge(){const n=debts.filter(d=>Number(d.saldo)>0).length;const b=$("#debtBadge");if(b){b.textContent=n;b.classList.toggle("hidden",n===0)}updateNotificationDot()}
function updateNotificationDot(){const low=products.filter(p=>productStock(p)<=Number(p.stockMinimo||appSettings.lowStockDefault||0)).length;const debt=debts.filter(d=>Number(d.saldo)>0).length;const dot=$("#notificationBtn i");if(dot)dot.classList.toggle("hidden",!appSettings.notifications||!(low+debt))}

function normalizeVariants(p){return Array.isArray(p?.variants)?p.variants.map(v=>({id:v.id||uid(),name:v.name||v.nombre||"Variante",sku:v.sku||"",stock:Number(v.stock||0),precio:Number(v.precio??p.precio??0),costo:Number(v.costo??p.costo??0)})):[]}
function productStock(p){const vs=normalizeVariants(p);return p?.hasVariants&&vs.length?vs.reduce((a,v)=>a+v.stock,0):Number(p?.stock||0)}
function productLabel(p){return p?.hasVariants&&p?.variantLabel?`${p.nombre} · ${p.variantLabel}`:p?.nombre||"Producto"}

function dashboardHTML(){
 const currentMonth=new Date().toISOString().slice(0,7);
 const cashRows=movements.filter(x=>monthKey(x.fecha)===currentMonth);
 const cashOpening=cashBalanceBefore(currentMonth);
 const cashIncome=cashRows.filter(x=>x.tipo!=="egreso"&&x.tipo!=="devolucion").reduce((a,x)=>a+Number(x.monto||0),0);
 const cashExpense=cashRows.filter(x=>x.tipo==="egreso"||x.tipo==="devolucion").reduce((a,x)=>a+Math.abs(Number(x.monto||0)),0);
 const closing=cashOpening+cashIncome-cashExpense;
 const key=todayKey(new Date()),todaySales=sales.filter(s=>todayKey(s.fecha||s.creadoEn)===key),todayTotal=todaySales.reduce((a,s)=>a+Number(s.total||0),0),todayCount=todaySales.length,totalDebt=debts.reduce((a,d)=>a+Number(d.saldo||0),0),low=products.filter(p=>productStock(p)<=Number(p.stockMinimo||0)).length;
 const days=[];for(let i=6;i>=0;i--){const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-i);const k=todayKey(d),daySales=sales.filter(s=>todayKey(s.fecha||s.creadoEn)===k),sum=daySales.reduce((a,s)=>a+Number(s.total||0),0);days.push({d,k,sum,count:daySales.length,label:new Intl.DateTimeFormat("es-AR",{weekday:"short"}).format(d).replace(".","").slice(0,3)})}
 const max=Math.max(...days.map(x=>x.sum),1);
 return `<div class="hero"><div><h1>Todo bajo control.</h1><p>Ventas reales, stock vivo y cuentas por cobrar en una sola vista.</p></div><div class="hero-actions"><button class="btn" data-view="inventory">${use("i-box")} Inventario</button><button class="btn primary" data-view="sales">${use("i-plus")} Nueva venta</button></div></div>
 <div class="metric-grid">
 <article class="metric accent-sales"><div class="metric-top"><span>VENTAS DE HOY</span><div class="metric-icon">${use("i-cart")}</div></div><div class="metric-value">${money(todayTotal)}</div><div class="metric-foot"><strong>${todayCount}</strong> ${todayCount===1?"venta":"ventas"} registradas hoy</div></article>
 <article class="metric accent-profit"><div class="metric-top"><span>GANANCIAS DE HOY</span><div class="metric-icon green">${use("i-money")}</div></div><div class="metric-value">${money(todaySales.reduce((a,s)=>a+saleProfit(s),0))}</div><div class="metric-foot">Margen estimado de ventas cobradas y fiadas</div></article>
 <article class="metric"><div class="metric-top"><span>CLIENTES</span><div class="metric-icon green">${use("i-users")}</div></div><div class="metric-value">${customers.length}</div><div class="metric-foot">Clientes registrados</div></article>
 <article class="metric accent-cash-close"><div class="metric-top"><span>CAJA AL CIERRE</span><div class="metric-icon green">${use("i-chart")}</div></div><div class="metric-value">${money(closing)}</div><div class="metric-foot">Este saldo pasa al próximo mes</div></article><article class="metric"><div class="metric-top"><span>POR COBRAR</span><div class="metric-icon red">${use("i-credit")}</div></div><div class="metric-value">${money(totalDebt)}</div><div class="metric-foot">${debts.filter(d=>Number(d.saldo)>0).length} cuentas pendientes</div></article>
 </div>
 <div class="dashboard-grid dashboard-grid-wide"><section class="panel sales-movement"><div class="panel-head"><div><div class="panel-title">Movimiento de ventas</div><span class="muted">Últimos 7 días · datos reales</span></div><button class="panel-link" data-view="sales">Ver ventas</button></div><div class="sales-chart">${days.map(x=>`<div class="chart-col"><div class="chart-value">${x.sum?money(x.sum).replace("$","$"):""}</div><div class="bar-wrap"><div class="bar-real" style="height:${Math.max(x.sum?6:2,(x.sum/max)*100)}%"></div></div><strong>${x.label}</strong><small>${x.count} ${x.count===1?"venta":"ventas"}</small></div>`).join("")}</div></section>
 <section class="panel"><div class="panel-head"><div><div class="panel-title">Actividad reciente</div><span class="muted">Últimas operaciones</span></div><button class="panel-link" data-view="sales">Ver todo</button></div>${sales.slice(0,6).map(s=>saleActivity(s)).join("")||`<div class="empty-large">Todavía no hay ventas. Tu primera venta aparecerá acá ✨</div>`}</section></div>
 <div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><div class="panel-title">Cuentas por cobrar</div><span class="muted">Clientes con saldo pendiente</span></div><button class="panel-link" data-view="debts">Ver deudas</button></div>${debts.filter(d=>Number(d.saldo)>0).slice(0,5).map(d=>`<div class="activity-row"><div class="customer-mini-avatar">${esc((d.cliente||"?").charAt(0).toUpperCase())}</div><div class="activity-text"><strong>${esc(d.cliente)}</strong><small>${d.vencimiento?`Vence ${esc(d.vencimiento)}`:"Sin vencimiento"}</small></div><div class="activity-value debt-value">${money(d.saldo)}</div></div>`).join("")||`<div class="empty-large">No hay cuentas pendientes 🎉</div>`}</section><section class="panel"><div class="panel-head"><div><div class="panel-title">Stock para revisar</div><span class="muted">Productos que necesitan reposición</span></div><button class="panel-link" data-view="inventory">Inventario</button></div>${products.filter(p=>productStock(p)<=Number(p.stockMinimo||0)).slice(0,5).map(p=>`<div class="activity-row"><div class="product-avatar">${use("i-box")}</div><div class="activity-text"><strong>${esc(p.nombre)}</strong><small>${p.hasVariants?`${normalizeVariants(p).length} variantes · `:""}${productStock(p)} unidades disponibles</small></div><div class="activity-value low-stock">Reponer</div></div>`).join("")||`<div class="empty-large">Todo el stock está saludable 🎉</div>`}</section></div>`;
}
function saleActivity(s){const name=s.cliente&&s.cliente!=="Consumidor final"?s.cliente:"Consumidor final";return `<div class="activity-row sale-activity"><div class="sale-icon">${use("i-cart")}</div><div class="activity-text"><strong>${esc(name)}</strong><small>${dateLabel(s.fecha||s.creadoEn)} · ${esc(paymentLabel(s.formaPago))} · ${Number(s.items?.length||0)} ${Number(s.items?.length||0)===1?"producto":"productos"}</small></div><div class="activity-value">${money(s.total)}</div></div>`}
function paymentLabel(x){return ({efectivo:"Efectivo",transferencia:"Transferencia",tarjeta:"Tarjeta",fiado:"Fiado"}[x]||x||"Pago")}
function transportIcon(name){
  const n=String(name||"").toLowerCase();
  const cls=n.replace(/[^a-z]+/g,'');
  let body;
  if(n.includes("correo")) body=`<path d="M8 12h32M11 18h26M14 24h20" stroke="currentColor" stroke-width="3" stroke-linecap="round"/><path d="M11 30h26" stroke="currentColor" stroke-width="3" stroke-linecap="round"/>`;
  else if(n.includes("via")) body=`<path d="M9 29h30l-3-13H16z" fill="currentColor" opacity=".18"/><path d="M9 29h30l-3-13H16zM12 29v5M35 29v5" stroke="currentColor" stroke-width="3" stroke-linejoin="round"/><circle cx="16" cy="35" r="3" fill="currentColor"/><circle cx="34" cy="35" r="3" fill="currentColor"/>`;
  else if(n.includes("uber")) body=`<path d="M14 10h20v8H14z" fill="currentColor" opacity=".15"/><path d="M14 10h20v8H14zM12 31l5-13h12l6 13M21 18v13" stroke="currentColor" stroke-width="3" stroke-linejoin="round"/><circle cx="17" cy="33" r="3" fill="currentColor"/><circle cx="34" cy="33" r="3" fill="currentColor"/>`;
  else if(n.includes("andreani")) body=`<path d="M9 29 24 9l15 20" stroke="currentColor" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/><path d="M15 29h18" stroke="currentColor" stroke-width="3" stroke-linecap="round"/>`;
  else if(n.includes("personal")) body=`<path d="M12 13h24v11H12z" fill="currentColor" opacity=".14"/><path d="M12 13h24v11H12zM17 24v5M31 24v5M16 10h16" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>`;
  else body=`<path d="M14 10h20v20H14z" fill="none" stroke="currentColor" stroke-width="3"/><path d="M19 17h10M19 23h7" stroke="currentColor" stroke-width="3" stroke-linecap="round"/>`;
  return `<span class="transport-icon transport-${cls}"><svg viewBox="0 0 48 48" aria-hidden="true">${body}</svg></span>`;
}

function monthName(key){if(!key)return '';const [y,m]=key.split('-');return new Intl.DateTimeFormat('es-AR',{month:'long',year:'numeric'}).format(new Date(Number(y),Number(m)-1,1))}
function cashBalanceBefore(month){return movements.filter(x=>monthKey(x.fecha)<month).reduce((a,x)=>a+(x.tipo==='egreso'||x.tipo==='devolucion'?-Math.abs(Number(x.monto||0)):Number(x.monto||0)),0)}
function cashNet(rows){return rows.reduce((a,x)=>a+(x.tipo==='egreso'||x.tipo==='devolucion'?-Math.abs(Number(x.monto||0)):Number(x.monto||0)),0)}
function transportOptions(selected=''){
 const opts=[['Entrega Personal','Entrega Personal'],['Correo Argentino','Correo Argentino'],['Via Cargo','Via Cargo'],['Uber/Didi Moto','Uber/Didi Moto'],['Andreani','Andreani'],['Otro','Otro']];
 return opts.map(([v,l])=>`<button type="button" class="transport-choice ${selected===v?'active':''}" data-transport="${esc(v)}">${transportIcon(v)}<span>${esc(l)}</span></button>`).join('')
}
function monthKey(d){if(!d)return "";if(d.toDate)d=d.toDate();if(typeof d?.seconds==="number")d=new Date(d.seconds*1000);if(typeof d==="string")d=new Date(d);return new Intl.DateTimeFormat("en-CA",{timeZone:"America/Argentina/Buenos_Aires",year:"numeric",month:"2-digit"}).format(d).slice(0,7)}
function saleProfit(s){return (s.items||[]).reduce((a,i)=>a+(Number(i.precio||0)-Number(i.costo||0))*Number(i.cantidad||0),0)-Number(s.descuento||0)}
