async function bulkDeleteProducts(ids){if(!ids.length)return;if(!confirm(`¿Eliminar ${ids.length} producto${ids.length===1?"":"s"} seleccionado${ids.length===1?"":"s"}?`))return;try{const batch=writeBatch(db),base=`usuarios/${currentUser.uid}/productos`;ids.forEach(id=>batch.delete(doc(db,base,id)));await batch.commit();notify(`${ids.length} producto${ids.length===1?"":"s"} eliminado${ids.length===1?"":"s"}`);renderInventory()}catch(e){notify("No se pudieron eliminar los productos")}}

async function getImageKitAuth(){
  const r=await fetch("/api/imagekit-auth");
  if(!r.ok)throw new Error("ImageKit todavía no está configurado en Vercel");
  return r.json();
}
async function uploadProductImage(file){
  if(!IMAGEKIT_PUBLIC_KEY)throw new Error("Falta configurar la Public Key de ImageKit");
  if(!IMAGEKIT_ENDPOINT)throw new Error("Falta configurar el URL Endpoint de ImageKit");
  const authData=await getImageKitAuth();
  const fd=new FormData();
  fd.append("file",file);
  fd.append("fileName",`${uid()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,"-")}`);
  fd.append("folder","/ineo/productos");
  fd.append("publicKey",IMAGEKIT_PUBLIC_KEY);
  fd.append("signature",authData.signature);
  fd.append("expire",authData.expire);
  fd.append("token",authData.token);
  fd.append("useUniqueFileName","true");
  fd.append("tags","ineo,producto");
  const r=await fetch("https://upload.imagekit.io/api/v1/files/upload",{method:"POST",body:fd});
  const raw=await r.text();
  let data={}; try{data=JSON.parse(raw)}catch(_){}
  if(!r.ok||!data.url)throw new Error(data.message||`ImageKit rechazó la subida (${r.status})`);
  return data.url;
}
