  for(const p of pay.rows){if(p.method!=="fiado")batch.set(doc(collection(db,base+"/movimientosCaja")),{tipo:"venta",concepto:`Venta · ${c?.nombre||"Consumidor final"}`,monto:p.amount,formaPago:p.method,ventaId:saleRef.id,fecha:serverTimestamp()})}
